from __future__ import annotations
import math
import sys
sys.path.insert(0, \"source\")
import quimb.tensor as qtn


def ring_edges(n):
    return [(i, (i + 1) % n) for i in range(n)]


def k4_edges():
    return [(0, 1), (0, 2), (0, 3), (1, 2), (1, 3), (2, 3)]


def grid_2x3_edges():
    # 0-1-2
    # | | |
    # 3-4-5
    return [(0, 1), (1, 2), (3, 4), (4, 5), (0, 3), (1, 4), (2, 5)]


def build(edges, D, phys, seed):
    return qtn.TN_from_edges_rand(
        edges=edges, D=D, phys_dim=phys, seed=seed, dtype=\"float64\"
    )


def gauge(tn, iters=2000, tol=1e-12):
    gauges = {}
    tn.gauge_all_simple_(max_iterations=iters, tol=tol, gauges=gauges)
    return gauges


def relerr(a, b):
    a, b = float(a), float(b)
    denom = max(abs(a), abs(b), 1e-300)
    return abs(a - b) / denom


cases = []

# trees (gloops=0): exact for any gauge
for n in (2, 3, 4, 5, 6, 7):
    for seed in (1, 7, 99):
        for D in (2, 3):
            cases.append((\"tree\", n, D, 2, seed, 0))

# rings (single loop): gloops=max_size=n
for n in (3, 4, 5, 6):
    for seed in (3, 11):
        cases.append((\"ring\", n, 2, 2, seed, n))

# K4 (3 independent triangles): max_size=3
for seed in (5, 42):
    cases.append((\"k4\", 4, 2, 2, seed, 3))

# 2x3 grid (2 independent squares): max_size=4
for seed in (8, 21):
    cases.append((\"grid2x3\", 6, 2, 2, seed, 4))


def run_one(kind, n, D, phys, seed, loop_order):
    edges = {
        \"ring\": ring_edges(n),
        \"k4\": k4_edges(),
        \"grid2x3\": grid_2x3_edges(),
    }.get(kind, None)

    if kind == \"tree\":
        tn = qtn.TN_rand_tree(n=n, D=D, phys_dim=phys, max_degree=3, seed=seed)
    else:
        tn = build(edges, D, phys, seed)

    results = []
    for equalize in (False, True):
        for autoreduce in (True, False):
            t = tn.copy()
            exact = t.norm()  # pre-equalize reference (exponent 0)
            if equalize:
                t.equalize_norms_(1.0)
            gauges = gauge(t)
            recon = t.norm_gloop_expand(
                gloops=loop_order,
                gauges={k: v.copy() for k, v in gauges.items()},
                autoreduce=autoreduce,
            )
            re = relerr(exact, recon)
            results.append((equalize, autoreduce, float(exact), float(recon), re))
    return results


fails = 0
total = 0
for kind, n, D, phys, seed, loop_order in cases:
    for equalize, autoreduce, exact, recon, re in run_one(kind, n, D, phys, seed, loop_order):
        total += 1
        tol = 1e-6
        ok = re < tol and math.isfinite(recon)
        if not ok:
            fails += 1
            print(f\"FAIL {kind} n={n} D={D} seed={seed} loop={loop_order} \"
                  f\"eq={equalize} ar={autoreduce}: exact={exact:.6e} \"
                  f\"recon={recon:.6e} relerr={re:.3e}\")
        else:
            tag = f\"{kind} n={n} D={D} seed={seed} loop={loop_order} eq={equalize} ar={autoreduce}\"
            print(f\"ok   {tag}: relerr={re:.2e}\")

print(f\"\\n{total-fails}/{total} passed, {fails} failed\")
sys.exit(1 if fails else 0)
